#!/usr/bin/env python3
from __future__ import annotations
import base64, gzip, json
from pathlib import Path

TARGET = Path("docs/data/biblia-explicata/nt-semantic-review-spec/06-romani.json")
ENCODED = "_REMAINDER"

correct = json.loads(gzip.decompress(base64.b64decode(ENCODED)).decode("utf-8"))
if not TARGET.exists():
    raise SystemExit("[Romans wave1 spec fix] target spec missing")
current = json.loads(TARGET.read_text(encoding="utf-8"))
if current.get("bookId") != "romani" or correct.get("bookId") != "romani":
    raise SystemExit("[Romans wave1 spec fix] unexpected book")

# Only snapshot hashes are allowed to differ. Review actions, rationales and rewrites
# must be byte-for-byte equivalent at the JSON value level before correcting hashes.
def without_hashes(doc):
    clone = json.loads(json.dumps(doc, ensure_ascii=False))
    for item in clone.get("decisions", {}).values():
        item.pop("expectedCurrentSnapshotSha256", None)
    return clone

if without_hashes(current) != without_hashes(correct):
    raise SystemExit("[Romans wave1 spec fix] current spec differs from frozen reviewed content beyond snapshot hashes")
if current == correct:
    print("Romans wave1 spec fix: snapshot hashes already aligned to reviewed presemantic copy.")
else:
    TARGET.write_text(json.dumps(correct, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print("Romans wave1 spec fix: aligned 68 expected snapshots to the exact reviewed corpus; no review decisions changed.")
